    public void decodeGps_position_withData_test() {
        Map<String, Object> result = Gt06ProtocolDecoder.decodeGps(new Position("lat", "lon"), null, true, null);
        assertNotNull(result);
        assertEquals(2, result.size());
    }

    @Test
    public void decodeGps_withSatellites_test() {
        Map<String, Object> result = Gt06ProtocolDecoder.decodeGps(new Position("lat", "lon"), null, false, true);
        assertNotNull(result);
        assertTrue((Boolean)result.get("hasSatellites"));
    }

    @Test
    public void decodeGps_withSpeed_test() {
        Map<String, Object> result = Gt06ProtocolDecoder.decodeGps(new Position("lat", "lon"), null, false, false, true);
        assertNotNull(result);
        assertTrue((Boolean)result.get("hasSpeed"));
    }

    @Test
    public void decodeGps_withTimezone_test() {
        Map<String, Object> result = Gt06ProtocolDecoder.decodeGps(new Position("lat", "lon"), null, false, false, false, new TimeZone("UTC"));
        assertNotNull(result);
        assertEquals("UTC", (String)result.get("timezone"));
    }

